"use client";

import { useRouter } from "@bprogress/next/app";
import { zodResolver } from "@hookform/resolvers/zod";
import {
  PrismaJsonCommsConfig,
  PrismaJsonRetryConfig,
} from "@purplefish-ai/db/types";
import IconAdd from "@purplefish-ai/material-icons/icons/icon-add";
import IconCall from "@purplefish-ai/material-icons/icons/icon-call";
import IconClose from "@purplefish-ai/material-icons/icons/icon-close";
import IconMail from "@purplefish-ai/material-icons/icons/icon-mail";
import IconSms from "@purplefish-ai/material-icons/icons/icon-sms";
import { Button } from "@purplefish-ai/shadcn-ui/components/ui/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@purplefish-ai/shadcn-ui/components/ui/card";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
} from "@purplefish-ai/shadcn-ui/components/ui/form";
import { Input } from "@purplefish-ai/shadcn-ui/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@purplefish-ai/shadcn-ui/components/ui/select";
import { useMutation } from "@tanstack/react-query";
import { useState } from "react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import * as z from "zod";
import { isCommsConfig } from "@/common/libs/comms-sequence";
import { DaysOfWeek, type IScheduleRule } from "@/common/libs/schedule";
import { ScheduleRuleEditor } from "@/components/schedule-rule-editor";
import { TimezoneSelector } from "@/components/timezone-selector";
import { useOrganizationContext } from "@/contexts/organization-context";
import { type MinimalJob } from "@/server/libs/jobs";
import { useTRPC } from "@/trpc/client";
import { TemplateSelector } from "./template-selector";

const defaultCallingHours: IScheduleRule = {
  [DaysOfWeek.Monday]: [
    {
      start: "08:00",
      end: "19:30",
    },
  ],
  [DaysOfWeek.Tuesday]: [
    {
      start: "08:00",
      end: "19:30",
    },
  ],
  [DaysOfWeek.Wednesday]: [
    {
      start: "08:00",
      end: "19:30",
    },
  ],
  [DaysOfWeek.Thursday]: [
    {
      start: "08:00",
      end: "19:30",
    },
  ],
  [DaysOfWeek.Friday]: [
    {
      start: "08:00",
      end: "19:30",
    },
  ],
};

const formSchema = z.object({
  firstAction: z
    .object({
      channel: z.enum(["phone", "sms", "email"]),
      templateId: z.string().optional(),
    })
    .refine(
      (data) =>
        data.channel === "phone" ||
        (data.templateId && data.templateId.length > 0),
      {
        message: "Template is required for email and SMS channels",
      },
    ),
  retryIntervals: z.array(
    z.object({
      value: z.number().min(1),
      unit: z.enum(["minutes", "hours", "days"]),
      action: z
        .object({
          channel: z.enum(["phone", "sms", "email"]),
          templateId: z.string().optional(),
        })
        .default({
          channel: "phone",
        })
        .refine(
          (data) =>
            data.channel === "phone" ||
            (data.templateId && data.templateId.length > 0),
          {
            message: "Template is required for email and SMS channels",
          },
        ),
    }),
  ),
});

type FormData = z.infer<typeof formSchema>;

function convertLegacyConfig(
  commsConfig: PrismaJsonCommsConfig,
): PrismaJsonRetryConfig {
  const intervals: PrismaJsonRetryConfig["retryIntervals"] = [];
  for (let i = 1; i <= commsConfig.maxAttempts; i++) {
    intervals.push({
      value: commsConfig.intervalHours,
      unit: "hours",
      action: {
        channel: "phone",
      },
    });
  }
  return {
    retryIntervals: intervals,
  };
}

export function Sequencer({
  job,
  emailTemplates = [],
  smsTemplates = [],
}: {
  job: MinimalJob;
  emailTemplates?: {
    id: string;
    name: string;
  }[];
  smsTemplates?: {
    id: string;
    name: string;
  }[];
}) {
  const { organizationId } = useOrganizationContext();
  const trpc = useTRPC();
  const router = useRouter();

  const { mutate: updateJobTimezone } = useMutation(
    trpc.job.updateJobTimezone.mutationOptions({}),
  );

  const { mutate: updateJobCommsSequence } = useMutation(
    trpc.job.updateJobCommsSequence.mutationOptions({}),
  );

  const { mutate: updateJobCallingHours } = useMutation(
    trpc.job.updateJobCallingHours.mutationOptions({}),
  );

  const onTimezoneChange = async (timezone: string) => {
    updateJobTimezone(
      {
        organizationId,
        jobId: job.id,
        timezone,
      },
      {
        onSuccess: () => {
          toast.success("Timezone updated successfully");
          // Refresh the router cache to ensure fresh data on navigation
          router.refresh();
        },
        onError: () => {
          toast.error("Failed to update timezone");
        },
      },
    );
  };

  const defaultInterval = {
    value: 45,
    unit: "minutes" as const,
    action: {
      channel: "phone" as const,
    },
  };

  const getDefaultValues = (): FormData => {
    // Create base config
    const baseConfig: FormData = {
      firstAction: {
        channel: "phone",
      },
      retryIntervals: [],
    };

    // Return default if no sequence exists
    if (!job.commsSequence) {
      return baseConfig;
    }

    // Check if it's the legacy format
    if (isCommsConfig(job.commsSequence)) {
      const legacyConfig = convertLegacyConfig(job.commsSequence);
      return formSchema.parse({
        ...baseConfig,
        ...legacyConfig,
      });
    }

    // Use new format or default
    return formSchema.parse({
      ...baseConfig,
      ...job.commsSequence,
    });
  };

  const form = useForm<FormData>({
    resolver: zodResolver(formSchema),
    defaultValues: getDefaultValues(),
  });

  const retryIntervals = form.watch("retryIntervals");
  const firstAction = form.watch("firstAction");

  const [scheduleRule, setScheduleRule] = useState<IScheduleRule>(() => {
    try {
      const jobScheduleRule = job.scheduleRule
        ? (job.scheduleRule as unknown as IScheduleRule)
        : null;
      return (
        jobScheduleRule || {
          ...defaultCallingHours,
        }
      );
    } catch {
      return {
        ...defaultCallingHours,
      };
    }
  });

  const handleAddInterval = () => {
    const currentIntervals = form.getValues("retryIntervals");
    form.setValue("retryIntervals", [...currentIntervals, defaultInterval]);
  };

  // Removed unused updateInterval function

  const handleRemoveInterval = (index: number) => {
    const currentIntervals = form.getValues("retryIntervals");
    form.setValue(
      "retryIntervals",
      currentIntervals.filter((_, i) => i !== index),
    );
  };

  const onSubmit = async (data: FormData) => {
    const config: PrismaJsonRetryConfig = {
      firstAction: data.firstAction,
      retryIntervals: data.retryIntervals.map((interval) => ({
        value: interval.value,
        unit: interval.unit,
        action: interval.action,
      })),
    };

    try {
      // Save comms sequence first
      await new Promise<void>((resolve, reject) => {
        updateJobCommsSequence(
          {
            organizationId,
            jobId: job.id,
            commsSequence: config,
          },
          {
            onSuccess: () => resolve(),
            onError: () =>
              reject(new Error("Failed to update communication sequence")),
          },
        );
      });

      // Save calling hours
      await new Promise<void>((resolve, reject) => {
        updateJobCallingHours(
          {
            organizationId,
            jobId: job.id,
            scheduleRule,
          },
          {
            onSuccess: () => resolve(),
            onError: () => reject(new Error("Failed to update calling hours")),
          },
        );
      });

      toast.success("Communication configuration saved successfully");
    } catch {
      toast.error("Failed to save communication configuration");
    }
  };

  return (
    <Card className="max-w-4xl">
      <CardHeader className="border-b">
        <CardTitle className="flex items-center gap-2">
          <IconCall className="text-muted-foreground h-5 w-5" />
          Communication Settings
        </CardTitle>
        <p className="text-muted-foreground mt-2 text-sm">
          Configure the sequence of communication attempts for this job.
        </p>
      </CardHeader>

      <CardContent>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
            <div className="mt-4 rounded-lg border">
              <div className="p-4">
                <div className="space-y-3">
                  <TimezoneSelector
                    key={`timezone-${job.id}-${job.timezone}`}
                    initialTimezone={job.timezone || "America/New_York"}
                    onTimezoneChange={onTimezoneChange}
                  />
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <div className="bg-card hover:bg-accent/5 relative mt-4 rounded-lg border p-4 transition-colors">
                <div className="flex items-start gap-4">
                  <FormField
                    control={form.control}
                    name="firstAction.channel"
                    render={({ field }) => (
                      <FormItem className="flex-1">
                        <FormLabel>Initial Contact Method</FormLabel>
                        <Select
                          onValueChange={(value) => {
                            field.onChange(value);
                            const clearTemplate =
                              value === "phone" ||
                              value !== firstAction.channel;
                            if (clearTemplate) {
                              form.setValue(
                                "firstAction.templateId",
                                undefined,
                              );
                            }
                          }}
                          defaultValue={field.value}
                        >
                          <FormControl>
                            <SelectTrigger className="h-9">
                              <SelectValue />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {[
                              {
                                value: "phone",
                                label: "Phone Call",
                              },
                              {
                                value: "sms",
                                label: "SMS Message",
                              },
                              {
                                value: "email",
                                label: "Email",
                              },
                            ].map((type) => (
                              <SelectItem key={type.value} value={type.value}>
                                <div className="flex items-center gap-2">
                                  {type.value === "phone" ? (
                                    <IconCall className="h-4 w-4" />
                                  ) : type.value === "sms" ? (
                                    <IconSms className="h-4 w-4" />
                                  ) : (
                                    <IconMail className="h-4 w-4" />
                                  )}
                                  {type.label}
                                </div>
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </FormItem>
                    )}
                  />
                </div>
                {firstAction.channel === "sms" && (
                  <div className="mt-4 pl-[calc(24px+1rem)]">
                    <FormField
                      control={form.control}
                      name="firstAction.templateId"
                      render={({ field }) => (
                        <FormItem>
                          <TemplateSelector
                            id="first-sms-template"
                            label="SMS Notification Template"
                            templates={smsTemplates}
                            value={field.value ?? undefined}
                            onValueChange={field.onChange}
                            placeholder="Select an SMS template"
                            channelName="SMS"
                          />
                        </FormItem>
                      )}
                    />
                  </div>
                )}
                {firstAction.channel === "email" && (
                  <div className="mt-4 pl-[calc(24px+1rem)]">
                    <FormField
                      control={form.control}
                      name="firstAction.templateId"
                      render={({ field }) => (
                        <FormItem>
                          <TemplateSelector
                            id="first-email-template"
                            label="Email Notification Template"
                            templates={emailTemplates}
                            value={field.value ?? undefined}
                            onValueChange={field.onChange}
                            placeholder="Select an email template"
                            channelName="email"
                          />
                        </FormItem>
                      )}
                    />
                  </div>
                )}
              </div>

              <div className="space-y-4">
                {retryIntervals.map((interval, index) => (
                  <div
                    key={index}
                    className="bg-card hover:bg-accent/5 relative rounded-lg border p-4 transition-colors"
                  >
                    <div className="bg-primary text-primary-foreground absolute -left-2 -top-2 flex h-6 w-6 items-center justify-center rounded-full text-xs font-medium">
                      {index + 1}
                    </div>
                    <div className="flex items-start gap-4">
                      <FormField
                        control={form.control}
                        name={`retryIntervals.${index}.value`}
                        render={({ field }) => (
                          <FormItem className="w-24">
                            <FormLabel>Wait for</FormLabel>
                            <FormControl>
                              <Input
                                type="number"
                                min="1"
                                className="h-9"
                                {...field}
                                onChange={(e) =>
                                  field.onChange(parseInt(e.target.value))
                                }
                              />
                            </FormControl>
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={form.control}
                        name={`retryIntervals.${index}.unit`}
                        render={({ field }) => (
                          <FormItem className="flex-1">
                            <FormLabel>Time Unit</FormLabel>
                            <Select
                              onValueChange={field.onChange}
                              defaultValue={field.value}
                            >
                              <FormControl>
                                <SelectTrigger className="h-9">
                                  <SelectValue />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {[
                                  {
                                    value: "minutes",
                                    label: "Minutes",
                                  },
                                  {
                                    value: "hours",
                                    label: "Hours",
                                  },
                                  {
                                    value: "days",
                                    label: "Days",
                                  },
                                ].map((unit) => (
                                  <SelectItem
                                    key={unit.value}
                                    value={unit.value}
                                  >
                                    {unit.label}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={form.control}
                        name={`retryIntervals.${index}.action.channel`}
                        render={({ field }) => (
                          <FormItem className="flex-1">
                            <FormLabel>Contact Method</FormLabel>
                            <Select
                              onValueChange={(value) => {
                                field.onChange(value);
                                const clearTemplate =
                                  value === "phone" ||
                                  value !== interval.action.channel;
                                if (clearTemplate) {
                                  form.setValue(
                                    `retryIntervals.${index}.action.templateId`,
                                    undefined,
                                  );
                                }
                              }}
                              defaultValue={field.value}
                            >
                              <FormControl>
                                <SelectTrigger className="h-9">
                                  <SelectValue />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {[
                                  {
                                    value: "phone",
                                    label: "Phone Call",
                                  },
                                  {
                                    value: "sms",
                                    label: "SMS Message",
                                  },
                                  {
                                    value: "email",
                                    label: "Email",
                                  },
                                ].map((type) => (
                                  <SelectItem
                                    key={type.value}
                                    value={type.value}
                                  >
                                    <div className="flex items-center gap-2">
                                      {type.value === "phone" ? (
                                        <IconCall className="h-4 w-4" />
                                      ) : type.value === "sms" ? (
                                        <IconSms className="h-4 w-4" />
                                      ) : (
                                        <IconMail className="h-4 w-4" />
                                      )}
                                      {type.label}
                                    </div>
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          </FormItem>
                        )}
                      />
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="hover:bg-destructive/10 hover:text-destructive mt-2"
                        onClick={() => handleRemoveInterval(index)}
                      >
                        <IconClose className="h-4 w-4" />
                        <span className="sr-only">Remove interval</span>
                      </Button>
                    </div>
                    {interval.action.channel === "sms" && (
                      <div className="mt-4 pl-[calc(24px+1rem)]">
                        <FormField
                          control={form.control}
                          name={`retryIntervals.${index}.action.templateId`}
                          render={({ field }) => (
                            <FormItem>
                              <TemplateSelector
                                id={`sms-template-${index}`}
                                label="SMS Notification Template"
                                templates={smsTemplates}
                                value={field.value ?? undefined}
                                onValueChange={field.onChange}
                                placeholder="Select an SMS template"
                                channelName="SMS"
                              />
                            </FormItem>
                          )}
                        />
                      </div>
                    )}
                    {interval.action.channel === "email" && (
                      <div className="mt-4 pl-[calc(24px+1rem)]">
                        <FormField
                          control={form.control}
                          name={`retryIntervals.${index}.action.templateId`}
                          render={({ field }) => (
                            <FormItem>
                              <TemplateSelector
                                id={`email-template-${index}`}
                                label="Email Notification Template"
                                templates={emailTemplates}
                                value={field.value ?? undefined}
                                onValueChange={field.onChange}
                                placeholder="Select an email template"
                                channelName="email"
                              />
                            </FormItem>
                          )}
                        />
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <div className="flex justify-between pt-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleAddInterval}
                  className="flex items-center gap-2"
                >
                  <IconAdd className="h-4 w-4" />
                  Add New Interval
                </Button>
              </div>

              <div className="mt-8 rounded-lg border">
                <ScheduleRuleEditor
                  scheduleRule={scheduleRule}
                  setScheduleRule={setScheduleRule}
                  initialExpanded={true}
                />
              </div>
            </div>

            <div className="flex justify-end pt-2">
              <Button
                type="submit"
                className="bg-primary text-primary-foreground hover:bg-primary/90"
              >
                Save Changes
              </Button>
            </div>
          </form>
        </Form>
      </CardContent>
    </Card>
  );
}

