import { db } from "@purplefish-ai/db/server";

import { JobSource, JobStatus } from "@/common/models/jobs";
import { inngest } from "@/server/inngest/client";
import { createCronTrigger, handleException } from "@/server/inngest/utils";
import {
  getTempworksCandidatesPageTotal,
  getTempworksIntegrations,
  syncTempworksCandidatesForPage,
} from "@/server/libs/ats/tempworks";

export const syncTempworksCandidatesFunction = inngest.createFunction(
  {
    id: "sync-tempworks-candidates",
  },
  [
    createCronTrigger("*/10 * * * *"), // Run every 10 minutes
  ],
  async ({ step }) => {
    const integrations = await step.run(
      "get-tempworks-integrations",
      async () => {
        try {
          const tempworksIntegrations = await getTempworksIntegrations();

          return tempworksIntegrations.map((integration) => ({
            id: integration.id,
            organizationId: integration.organizationId,
          }));
        } catch (error) {
          handleException(error);
          throw error;
        }
      },
    );

    for (const integration of integrations) {
      const jobs = await step.run(
        `get-jobs-for-organization-${integration.organizationId}`,
        async () => {
          return await db.job.findMany({
            where: {
              organizationId: integration.organizationId,
              status: {
                not: JobStatus.CLOSED,
              },
              atsId: {
                not: null,
              },
              source: JobSource.ATS_TEMPWORKS,
            },
          });
        },
      );

      for (const job of jobs) {
        if (!job.atsId) {
          console.log(
            `Job ${String(job.id)} has no atsId while syncing Tempworks candidates. Skipping.`,
          );
          continue;
        }

        const numPages = await step.run(
          `get-num-pages-of-candidates-${String(job.id)}`,
          async () => {
            try {
              return getTempworksCandidatesPageTotal({
                tempworksIntegrationId: integration.id,
                jobOrderId: job.atsId! as string,
              });
            } catch (error) {
              handleException(error);
              throw error;
            }
          },
        );

        for (let page = 1; page <= numPages; page++) {
          await step.run(`sync-tempworks-candidates-page-${page}`, async () => {
            try {
              return syncTempworksCandidatesForPage({
                tempworksIntegrationId: integration.id,
                page,
                jobOrderId: job.atsId! as string,
              });
            } catch (error) {
              handleException(error);
              throw error;
            }
          });
        }
      }
    }
  },
);

