async function createQualificationsFromJobDescription({
  jobId,
  jobDescription,
  qualificationInstructions,
  screeningQuestions,
}: {
  jobId: string;
  jobDescription: string;
  qualificationInstructions: string;
  screeningQuestions?: string;
}) {
  const result = await generateObject({
    model: aiModel,
    abortSignal: AbortSignal.timeout(60000), // 1 minute
    schema: z.object({
      qualifications: z.array(
        z.object({
          type: z.enum(["mandatory", "preferred"]),
          value: z.string(),
          shouldIncludeInFlow: z.boolean(),
        }),
      ),
    }),
    prompt: `
You are an expert recruiter analyzing a job description to extract qualifications for candidate screening.

## Input Data

<job_description>
${jobDescription}
</job_description>

${
  screeningQuestions
    ? `
<additional_screening_questions>
${screeningQuestions}
</additional_screening_questions>
`
    : ""
}

${
  qualificationInstructions
    ? `
<custom_instructions>
${qualificationInstructions}
</custom_instructions>
`
    : ""
}

## Task Overview

Extract all qualifications from the job description and categorize them for a phone screening process. You need to:
1. Identify ALL qualifications mentioned in the job description
2. Select 2-4 key qualifications for the screening call flow
3. Categorize each qualification as "mandatory" or "preferred"
4. Format qualifications concisely and clearly

${
  screeningQuestions
    ? `
## Screening Questions Processing

IMPORTANT: Convert ALL screening questions into mandatory qualifications with shouldIncludeInFlow: true.

Conversion examples:
- "Are you comfortable working night shifts? (Desired answer yes)" → "Available to work night shifts"
- "Do you have reliable transportation?" → "Has reliable transportation"
- "How many years of customer service experience do you have?" → "Customer service experience"
- "Are you able to start within 2 weeks?" → "Available to start within 2 weeks"

If a desired answer is provided, incorporate it into the qualification criteria.
`
    : ""
}

## Selection Criteria for Call Flow Qualifications

Select 2-4 qualifications to include in the screening call${screeningQuestions ? ", PLUS all converted screening questions" : ""}:

### MUST Include:
1. **Experience qualifications**: e.g., "2+ years experience in customer service"
   - Always specify the number of years and field
2. **Education qualifications**: e.g., "Bachelor's degree in Engineering"
   - If none specified and pay < $30/hour: default to "High school diploma or GED"
   - If none specified and pay ≥ $30/hour: default to "Bachelor's degree"
3. **Certifications/Licenses**: e.g., "Valid nursing license"
4. **Hard requirements**: e.g., "Available for 2 weeks on site training"

### NEVER Include in Call Flow:
- Work authorization/visa requirements
- Physical requirements (lifting, standing, etc.)
- Soft skills (communication, organization, etc.)
- Resume formatting requirements

## Categorization Rules

### Mark as "mandatory" (but exclude from flow):
- Legal work authorization
- Physical abilities
- Technical safety knowledge

### Mark as "preferred" (and exclude from flow):
- Nice-to-have experience
- Soft skills
- Travel ability
- Industry familiarity

## Formatting Guidelines

1. Be concise and specific
2. Replace "/" with "or" for clarity
3. Remove parenthetical information by incorporating it into the main text
4. Example: "Experience with supplier certs (Material certs, etc)" → "1+ years experience with reviewing supplier certs"

## Output Requirements

For each qualification provide:
- "value": The concise qualification statement
- "type": Either "mandatory" or "preferred"
- "shouldIncludeInFlow": true for call flow questions, false otherwise

## Important Notes

- Avoid duplicates - merge similar qualifications
- Order flow qualifications by: Experience → Certifications → Education
- Focus on objective, verifiable qualifications
- Do NOT extract job responsibilities as qualifications
`,
  });

  await db.jobQualification.deleteMany({
    where: {
      jobId,
    },
  });

  await db.jobQualification.createMany({
    data: result.object.qualifications.map((qualification) => ({
      jobId,
      ...qualification,
    })),
  });
}

async function getDataFromJobDescription({
  headline,
  description,
  templateVariables,
}: {
  headline?: string | null;
  description: string;
  templateVariables: TemplateVariable[];
}) {
  const uniqueTemplateVariables = templateVariables.filter(
    (v, i, self) => self.findIndex((t) => t.key === v.key) === i,
  );

  return await generateObject({
    model: aiModel,
    abortSignal: AbortSignal.timeout(60000), // 1 minute
    schema: z.object({
      title: z.string().describe("The job title"),
      description: z.string().describe("The candidate-facing job description"),
      questions: z
        .array(
          z.object({
            question: z
              .string()
              .describe("The question that the candidate may ask"),
            answer: z.string().describe("The answer to the question"),
          }),
        )
        .describe("Questions that the candidate may ask"),
      templateVariables: z.object(
        uniqueTemplateVariables.reduce(
          (acc, templateVariable) => {
            acc[templateVariable.key] = z.string();
            return acc;
          },
          {} as Record<string, z.ZodType<string>>,
        ),
      ),
      canAutoLaunch: z
        .boolean()
        .describe(
          "Can this job be auto launched based on the criteria provided for auto launch",
        ),
      allowAgentNegotiation: z
        .boolean()
        .describe(
          "Should the agent be allowed to negotiate the pay rate with the candidate?",
        ),
    }),
    prompt: `
      Job Headline: ${headline}\n\n
      Job Description: ${description}\n\n

      The above are the details of a job that you are creating a flow for. Fill in the values for the provided template variables as JSON as well as a job title, 
      the candidate-facing description, hiring company's name, and candidate frequently asked questions. If you are unsure of a value, leave it blank. 
      Do not convert units or make any other changes to the values from the job description (e.g. don't convert hours 
      or a date range to time).

      When you are done, set the following fields:

      Set the "canAutoLaunch" field based on the following criteria. If any criteria sets it to false, it will override any other criteria:
      - If the max pay rate is less than or equal to $${fsdCriteria.MAX_HOURLY_SALARY} per hour, set to true. Else, set to false.

      Set the "allowAgentNegotiation" field based on the following criteria:
      - If the pay_rate_display variable is a range, set to false. Else, set to true. 
      For example, if the pay_rate_display is "$100-$120 per hour", set to false. If the pay_rate_display is "$100 per hour", set to true.

      The following are questions that the candidate may ask. Use the job description to answer these questions,
      and if you are unsure, leave it blank:
      1. Does the job provide benefits? 

      For each template variable, use the specific instructions provided. Look at the Job Headline first to see if the data is 
      present there, and if not, fall back to the Job Description.
      \n\nTemplate Variables:\n${uniqueTemplateVariables
        .map(
          (templateVariable) =>
            `* ${templateVariable.key}:
            Description: ${templateVariable.description} 
          ${templateVariable.llmPrompt ? `Instructions: ${templateVariable.llmPrompt}` : ""}`,
        )
        .join("\n")}`,
  });
}

const populateTemplateVarsV2Schema = z.object({
  nodes: z.array(
    z
      .object({
        id: z.string().describe("The id of the node"),
        prompt: z.string().describe("The prompt of the node"),
        evaluationCriteria: z
          .string()
          .optional()
          .describe("The evaluation criteria for the node"),
        conditionToEnter: z
          .string()
          .optional()
          .describe("The condition to enter the node"),
      })
      .describe("A node in the graph"),
  ),
});

const getAcronymConversionPrompt = () => `
  Let's make sure we are pronouncing acronyms correctly.
  Spell tags are used to spell out words by reading them letter by letter.
  If you encounter an acronym that is less than 5 characters, use your best judgement to determine if it should be pronounced as a word or an acronym.
  If it should be pronounced as an acronym, prefix it with <spell> and suffix it with </spell> (e.g. IRS -> <spell>IRS</spell>, or AB -> <spell>AB</spell>)
  If it should be pronounced as a word, leave it as is (e.g. NASA -> NASA, HIPAA -> HIPAA)
`;

async function populateVariablesInFlow({
  nodes,
  variables,
  shouldConvertAcronyms = false,
}: {
  nodes: ScriptNode[];
  variables: JobVariableWithTemplateVariable[];
  shouldConvertAcronyms: boolean;
}) {
  const convertedNodes = convertMentionsToVariablesInNodes(nodes, variables);

  const variablesMap = variables.reduce(
    (acc, variable) => {
      acc[variable.templateVariable.key] = variable.value;
      return acc;
    },
    {} as Record<string, string>,
  );

  const simplerNodes = convertedNodes.map((node) => {
    const simplerNode: Record<string, string> = {
      id: node.id,
      prompt: node.prompt,
    };
    if (node.evaluationCriteria) {
      simplerNode.evaluationCriteria = node.evaluationCriteria;
    }
    if (node.conditionToEnter?.evaluationMatches) {
      simplerNode.conditionToEnter = node.conditionToEnter.evaluationMatches;
    }

    return simplerNode;
  });

  const nodesWithBrackets = simplerNodes.filter((node) =>
    Boolean(
      node.prompt?.includes("{{") ||
        node.evaluationCriteria?.includes("{{") ||
        node.conditionToEnter?.includes("{{"),
    ),
  );

  const result = await generateObject({
    model: aiModel,
    abortSignal: AbortSignal.timeout(60000), // 1 minute
    schema: populateTemplateVarsV2Schema,
    prompt: `
    The following is a list of nodes with template variables marked with {{variable_name}}.
    Using the provided values, update the nodes to replace the template variables. 
    Don't just insert the values into the nodes, make minor edits to the nodes text 
    to make the template variable values fit in fluently and smoothly. If there are any
    unknown template variables, remove the {{variable_name}} and replace it with /variable_name 
    (e.g. {{first_name}} -> /first_name, {{organization_name}} -> /organization_name, {{agent}} -> /agent, etc).

    ${shouldConvertAcronyms ? getAcronymConversionPrompt() : ""}

    Template Variables:
    ${JSON.stringify(variablesMap, null, 2)}
    Nodes:    
    ${JSON.stringify(nodesWithBrackets, null, 2)}
`,
  });
  // Update nodes and with the result
  for (const node of nodes) {
    const updatedNode = result.object.nodes.find((n) => n.id === node.id);
    if (!updatedNode) {
      continue;
    }
    node.prompt = updatedNode.prompt;
    if (updatedNode.evaluationCriteria) {
      node.evaluationCriteria = updatedNode.evaluationCriteria;
    }
    if (updatedNode.conditionToEnter && node.conditionToEnter) {
      node.conditionToEnter.evaluationMatches = updatedNode.conditionToEnter;
    }
  }

  return {
    nodes,
  };
}

// Look at the script template and get the variables that are needed for the job
// Look at the org notification templates and get the variables that are needed for the job
// Look at the voice prompt variables and get the variables that are needed for the job
// Return the unique variables
export const getVariablesToCreateForJob = async (
  scriptTemplateId: string,
  organizationId: string,
): Promise<TemplateVariable[]> => {
  const scriptTemplate = await db.scriptTemplate.findUniqueOrThrow({
    where: {
      id: scriptTemplateId,
      organizationId,
    },
    include: {
      variables: {
        include: {
          templateVariable: true,
        },
      },
    },
  });

  const variablesForScript = (
    scriptTemplate.variables as ScriptVariableWithTemplateVariable[]
  )
    .filter(
      (v) => v.templateVariable.type === TemplateVariableType.JOB.toString(),
    )
    .map((v) => v.templateVariable);

  const orgNotificationTemplates = await getOrgNotificationTemplates({
    organizationId,
    onlyReturnEnabled: true,
  });

  const variablesForNotifications = orgNotificationTemplates
    .flatMap((template) => template.variables)
    .map((v) => v.templateVariable)
    .filter(
      (templateVariable) =>
        templateVariable.type === TemplateVariableType.JOB.toString(),
    );

  const voicePrompts = await db.orgVoicePrompt.findMany({
    where: {
      organizationId,
    },
    include: {
      variables: {
        include: {
          templateVariable: true,
        },
      },
    },
  });

  const variablesForVoicePrompts = voicePrompts
    .flatMap((template) => template.variables)
    .map((v) => v.templateVariable)
    .filter(
      (templateVariable) =>
        templateVariable.type === TemplateVariableType.JOB.toString(),
    );

  const uniqueTemplateVariables = [
    ...variablesForScript,
    ...variablesForNotifications,
    ...variablesForVoicePrompts,
  ].filter((v, i, self) => self.findIndex((t) => t.key === v.key) === i);

  return uniqueTemplateVariables;
};

// Job has all the required variables
// Job has a valid number of qualifications
// Organization has auto-launch enabled
const shouldAutoLaunchJob = async (jobId: string) => {
  const job = await db.job.findUniqueOrThrow({
    where: {
      id: jobId,
    },
    include: {
      variables: {
        include: {
          templateVariable: true,
        },
      },
      qualifications: true,
      organization: true,
    },
  });

  // First check if the organization has auto-launch enabled
  if (!job.organization.autoLaunchJobsEnabled) {
    return false;
  }

  const allJobVariablesHaveValues = job.variables
    .filter(
      (v) => v.templateVariable.type === TemplateVariableType.JOB.toString(),
    )
    .every((v) => Boolean(v.value));

  const hasValidNumberOfQualifications =
    job.qualifications.filter(
      (q) =>
        q.type.toString() === JobQualificationType.MANDATORY.toString() &&
        q.shouldIncludeInFlow,
    ).length <= fsdCriteria.MAX_QUALIFICATIONS_TO_GENERATE;

  return allJobVariablesHaveValues && hasValidNumberOfQualifications;
};

export const activateAutoLaunchedJob = async ({
  organizationId,
  jobId,
}: {
  organizationId: string;
  jobId: string;
}) => {
  try {
    await db.job.update({
      where: {
        id: jobId,
      },
      data: {
        wasAutoLaunched: true,
      },
    });

    await setJobStatus({
      organizationId,
      jobId,
      status: JobStatus.ACTIVE.toString(),
    });
  } catch (error) {
    console.error("Error auto launching job", error);
    await db.job.update({
      where: {
        id: jobId,
      },
      data: {
        wasAutoLaunched: false,
        status: JobStatus.PAUSED.toString(),
      },
    });
  }
};

export const createJob = async ({
  organizationId,
  unformattedDescription,
  scriptTemplateId,
  atsId,
  clientId,
  createdByUserId,
  originalTitle,
  source,
  headline,
  emailBody,
  existingJobId,
  allowCallTransfers,
  screeningQuestions,
  schemaVersion,
}: {
  organizationId: string;
  unformattedDescription?: string | null;
  scriptTemplateId?: string;
  atsId?: string | null;
  clientId?: string | null;
  createdByUserId: string | null;
  originalTitle?: string | null;
  source: JobSource;
  headline?: string;
  emailBody?: string;
  existingJobId?: string;
  allowCallTransfers?: boolean;
  screeningQuestions?: string;
  schemaVersion?: string;
}): Promise<{
  job: Job;
}> => {
  // For v3 schema, create a minimal job without script template processing
  if (schemaVersion === "v3") {
    const { defaultInterviewPlan } = await import("@/common/models/stages");

    const jobData = {
      title: originalTitle || "New Job",
      originalDescription: unformattedDescription || "",
      description: unformattedDescription || "",
      organizationId,
      createdById: createdByUserId,
      atsId: sanitizeAtsId(atsId),
      clientId,
      source,
      schemaVersion: "v3",
      timezone: "America/New_York",
      scheduleRule: {},
      // Don't copy commsSequence here - it will be handled during template creation
      interviewPlan: defaultInterviewPlan,
    };

    const job = await db.job.create({
      data: jobData,
    });

    // Initialize empty interview builder state
    await db.job.update({
      where: {
        id: job.id,
      },
      data: {
        interviewBuilder: createEmptyInterviewBuilder(),
      },
    });

    return {
      job,
    };
  }

  // Original v2 flow
  if (!scriptTemplateId) {
    throw new Error("Script template is required for v2 jobs");
  }

  const scriptTemplate = await getScriptTemplate(
    organizationId,
    scriptTemplateId,
  );

  const variablesToCreateForJob = await getVariablesToCreateForJob(
    scriptTemplateId,
    organizationId,
  );

  const originalDescription = unformattedDescription || "";

  const jobDescriptionData = await getDataFromJobDescription({
    headline,
    description: originalDescription,
    templateVariables: variablesToCreateForJob,
  });

  const jobResponsibilities = formatAsBulletPoints(
    JSON.parse(
      jobDescriptionData.object.templateVariables[
        variableKeys.JOB_RESPONSIBILITIES
      ] ?? "[]",
    ) as string[],
  );

  const agentInstructions = await generateJobAgentInstructions(
    jobDescriptionData.object.questions,
  );
  const jobLocation =
    jobDescriptionData.object.templateVariables[variableKeys.JOB_LOCATION];

  const workSetting =
    jobDescriptionData.object.templateVariables[variableKeys.WORK_SETTING];
  const isRemoteJob = workSetting?.toLowerCase() === "remote";

  const timezone =
    isRemoteJob || !jobLocation
      ? "America/New_York"
      : (getTimezoneFromLocation(jobLocation) ?? "America/New_York");

  if (organizationId === MANAGED_STAFFING_ORG_ID) {
    const clientName =
      jobDescriptionData.object.templateVariables[
        variableKeys.CLIENT_NAME
      ]?.toLowerCase();

    const disableCallTransfer = Boolean(
      clientName && clientSpecificRequirements[clientName]?.disableCallTransfer,
    );

    if (disableCallTransfer) {
      allowCallTransfers = false;
      console.log(
        `Disabling call transfers for client ${clientName} on job ${clientId}`,
      );
    }
  }

  const jobData = {
    title: originalTitle ?? jobDescriptionData.object.title,
    originalDescription,
    jobResponsibilities,
    scriptTemplateId,
    organizationId,
    createdById: createdByUserId,
    atsId: sanitizeAtsId(atsId),
    clientId,
    agentInstructions,
    source,
    headline,
    jobEmailBody: emailBody,
    allowAgentNegotiation: jobDescriptionData.object.allowAgentNegotiation,
    maxAccessibleCreationStep: 0,
    timezone,
    scheduleRule: scriptTemplate.scheduleRule,
    allowCallTransfers,
    // Don't copy commsSequence here - it will be handled during template creation
  };

  const job = await db.job.upsert({
    where: {
      id: existingJobId ?? v4(),
    },
    create: jobData,
    update: jobData,
    include: {
      organization: {
        select: {
          qualificationInstructions: true,
        },
      },
    },
  });

  await createQualificationsFromJobDescription({
    jobId: job.id,
    jobDescription: originalDescription,
    qualificationInstructions: job.organization.qualificationInstructions ?? "",
    screeningQuestions,
  });

  await createJobVariables({
    jobId: job.id,
    templateVariables: variablesToCreateForJob,
    templateVariableValues: jobDescriptionData.object.templateVariables,
  });

  await createDefaultInterviewPlan({
    jobId: job.id,
  });

  const doesLLMRecommendAutoLaunch = jobDescriptionData.object.canAutoLaunch;
  const shouldAutoLaunch =
    doesLLMRecommendAutoLaunch && (await shouldAutoLaunchJob(job.id));

  await inngest.send({
    name: "purplefish/job.created",
    data: {
      organizationId,
      jobId: job.id,
      shouldAutoLaunch,
    },
  });

  return {
    job,
  };
};

/**
 * Creates a copy of an existing job without copying pipeline or other related values
 * @param organizationId - The organization ID
 * @param sourceJobId - The ID of the job to copy
 * @param createdByUserId - The ID of the user creating the copy
 * @returns The newly created job
 */
export const copyJob = async ({
  organizationId,
  sourceJobId,
  createdByUserId,
}: {
  organizationId: string;
  sourceJobId: string;
  createdByUserId: string | null;
}): Promise<Job> => {
  // Get the source job with all its related data
  const sourceJob = await getJobWithTemplate(organizationId, sourceJobId);

  // Get source job notification templates to prepare for mapping
  const sourceJobNotificationTemplates =
    await db.jobNotificationTemplate.findMany({
      where: {
        jobId: sourceJobId,
      },
    });

  // Create a new job with the same data but a new ID (without commsSequence initially)
  const newJobData = {
    title: `Copy of ${sourceJob.title}`,
    originalDescription: sourceJob.originalDescription,
    description: sourceJob.description,
    jobResponsibilities: sourceJob.jobResponsibilities,
    scriptTemplateId: sourceJob.scriptTemplateId,
    organizationId: sourceJob.organizationId,
    createdById: createdByUserId,
    atsId: null, // Don't copy the ATS ID to avoid conflicts
    clientId: null, // Don't copy the Client ID to avoid conflicts
    agentInstructions: sourceJob.agentInstructions,
    source: sourceJob.source,
    headline: sourceJob.headline,
    jobEmailBody: sourceJob.jobEmailBody,
    allowAgentNegotiation: sourceJob.allowAgentNegotiation,
    maxAccessibleCreationStep: sourceJob.maxAccessibleCreationStep,
    useAgentInstructions: sourceJob.useAgentInstructions,
    requiredSkills: sourceJob.requiredSkills,
    preferredSkills: sourceJob.preferredSkills,
    candidateDescription: sourceJob.candidateDescription,
    callScript: JSON.parse(
      JSON.stringify(sourceJob.callScript),
    ) as Prisma.InputJsonValue,
    // commsSequence will be set after remapping template IDs
    messagingEnabled: sourceJob.messagingEnabled,
    resumeCallsEnabled: sourceJob.resumeCallsEnabled,
    scheduleRule: sourceJob.scheduleRule as IScheduleRule,
    timezone: sourceJob.timezone,
    callLanguage: sourceJob.callLanguage,
    // Set status to paused by default for the new copy
    status: JobStatus.PAUSED.toString(),
    interviewPlan: sourceJob.interviewPlan,
    selectedAgentVoiceIds: sourceJob.selectedAgentVoiceIds,
  };

  // Create the new job (without commsSequence initially)
  const newJob = await db.job.create({
    data: newJobData,
  });

  // Copy job variables
  if (sourceJob.variables.length > 0) {
    await db.jobVariable.createMany({
      data: sourceJob.variables.map((variable) => ({
        jobId: newJob.id,
        templateVariableId: variable.templateVariableId,
        value: variable.value,
      })),
    });
  }

  // Copy job qualifications
  if (sourceJob.qualifications.length > 0) {
    await db.jobQualification.createMany({
      data: sourceJob.qualifications.map((qualification) => ({
        jobId: newJob.id,
        type: qualification.type,
        value: qualification.value,
        shouldIncludeInFlow: qualification.shouldIncludeInFlow,
        shouldIncludeInEmail: qualification.shouldIncludeInEmail,
      })),
    });
  }

  // Copy job notification templates and build ID mapping
  const templateIdMapping = new Map<string, string>();

  for (const template of sourceJobNotificationTemplates) {
    // Create a copy of the job notification template for the new job
    const newTemplate = await db.jobNotificationTemplate.create({
      data: {
        jobId: newJob.id,
        name: template.name,
        enabled: template.enabled,
        channel: template.channel,
        triggeredByState: template.triggeredByState,
        bodyTemplate: template.bodyTemplate,
        subjectTemplate: template.subjectTemplate,
        orgTemplateId: template.orgTemplateId,
        group: template.group,
        replyToRecruiter: template.replyToRecruiter,
        subject: template.subject,
        body: template.body,
      },
    });

    // Map old template ID to new template ID
    templateIdMapping.set(template.id, newTemplate.id);
  }

  // Remap commsSequence template IDs if the source job has a commsSequence
  if (sourceJob.commsSequence) {
    const remappedCommsSequence = await mapCommsSequenceTemplateIds(
      sourceJob.commsSequence,
      templateIdMapping,
    );

    // Update the new job with the remapped commsSequence
    if (remappedCommsSequence) {
      await db.job.update({
        where: {
          id: newJob.id,
        },
        data: {
          commsSequence: remappedCommsSequence,
        },
      });
    }
  }

  // Return only the basic job data to ensure it's serializable
  return newJob;
};

export const createJobFromCeipal = async ({
  organizationId,
  ceipalJob,
  scriptTemplateId,
  createdByUserId,
  emailSubject,
  emailBody,
}: {
  organizationId: string;
  ceipalJob: CeipalJobResponse;
  scriptTemplateId: string;
  createdByUserId: string | null;
  emailSubject?: string;
  emailBody?: string;
}): Promise<{
  jobId: string;
}> => {
  const existingJob = ceipalJob.JobCode
    ? await db.job.findFirst({
        where: {
          atsId: ceipalJob.JobCode,
          organizationId,
        },
      })
    : null;

  if (
    existingJob !== null &&
    existingJob.status === JobStatus.ACTIVE.toString()
  ) {
    console.info(
      `Job already exists for atsId ${ceipalJob.JobCode} and is active, skipping creation`,
    );

    await sendExistingJobMessage(existingJob.id);

    return {
      jobId: existingJob.id,
    };
  }

  const { job } = await createJob({
    organizationId,
    headline: emailSubject,
    unformattedDescription: ceipalJob.JobDescription,
    scriptTemplateId,
    atsId: ceipalJob.JobCode,
    clientId: ceipalJob.ClientJobID,
    createdByUserId: createdByUserId,
    originalTitle: ceipalJob.JobTitle,
    source: JobSource.ATS_CEIPAL,
    emailBody,
    existingJobId: existingJob?.id,
    allowCallTransfers: true,
  });

  return {
    jobId: job.id,
  };
};

