export const setJobStatus = async ({
  organizationId,
  jobId,
  status,
  userId,
}: {
  organizationId: string;
  jobId: string;
  status: string;
  userId?: string;
}) => {
  const currentJob = await db.job.findUniqueOrThrow({
    where: {
      id: jobId,
      organizationId,
    },
  });

  const isActivatingJob = status === JobStatus.ACTIVE.toString();

  // Validate that manual jobs don't have ATS IDs when activating
  if (
    isActivatingJob &&
    currentJob.source === JobSource.MANUAL.toString() &&
    currentJob.atsId
  ) {
    throw new Error(
      "Manual jobs should not have an ATS ID. Please remove the ATS ID from the job settings before activating, or change the integration source to match your ATS.",
    );
  }

  const activatedTimestamp = isActivatingJob
    ? {
        lastActivatedAt: new Date(),
      }
    : {};

  const job = await db.job.update({
    where: {
      id: jobId,
      organizationId,
    },
    data: {
      status,
      ...activatedTimestamp,
    },
  });

  if (isActivatingJob) {
    await inngest.send({
      name: "purplefish/job.activated",
      data: {
        jobId: job.id,
      },
    });
  }

  // If the status is updated for the first time, set the deployedAt timestamp
  if (!currentJob.deployedAt) {
    await db.job.update({
      where: {
        id: jobId,
        organizationId,
      },
      data: {
        deployedAt: new Date(),
      },
    });
  }

  console.log(
    `Job status updated to ${status} for job ${jobId} by user ${userId}`,
  );

  const opportunities = await db.opportunity.findMany({
    where: {
      jobId: jobId,
    },
  });

  console.log(
    `Re-configuring sequence items for ${opportunities.length} opportunities of job ${jobId}`,
  );

  if (isActivatingJob) {
    await Promise.all(
      opportunities.map(async (opportunity) => {
        await moveOpportunityToNextStage({
          opportunityId: opportunity.id,
        });
      }),
    );
  }

  return job;
};

