export const getFilteredJobs = async (
  organizationIds: string[],
  opts: {
    pageIndex: number;
    pageSize?: number;
    sorting?: SortingState;
    columnFilters?: ColumnFiltersState;
    query?: string;
    skipCount?: boolean;
  },
): Promise<{
  jobs: JobTableRow[];
  totalCount: number;
}> => {
  const pageIndex = opts.pageIndex;
  const pageSize = opts.pageSize ?? 30;

  const whereInputs: Prisma.JobWhereInput[] = [];

  // Search query must be processed before being used
  // https://github.com/prisma/prisma/issues/8939
  const searchQuery = sanitizeTsQuery(opts.query, {
    usePartialMatch: false,
  });
  const looseSearchQuery = buildLooseTsQuery(opts.query);

  if (opts.query && searchQuery) {
    whereInputs.push({
      OR: [
        // Search
        {
          title: {
            search: searchQuery,
            mode: "insensitive",
          },
        },
        {
          description: {
            search: searchQuery,
            mode: "insensitive",
          },
        },
        {
          jobResponsibilities: {
            search: searchQuery,
            mode: "insensitive",
          },
        },
        {
          candidateDescription: {
            search: searchQuery,
            mode: "insensitive",
          },
        },
        {
          agentInstructions: {
            search: searchQuery,
            mode: "insensitive",
          },
        },

        // Loosen search for title
        ...(looseSearchQuery
          ? [
              {
                title: {
                  search: looseSearchQuery,
                  mode: "insensitive" as const,
                },
              },
            ]
          : []),

        // Perfectly matches
        {
          id: {
            contains: opts.query.trim(),
            mode: "insensitive",
          },
        },
        {
          atsId: {
            contains: opts.query.trim(),
            mode: "insensitive",
          },
        },
        {
          clientId: {
            contains: opts.query.trim(),
            mode: "insensitive",
          },
        },
      ],
    });
  }

  const statuses = (opts.columnFilters?.find((filter) => filter.id === "status")
    ?.value ?? []) as string[];

  const statusWhereInput: Prisma.JobWhereInput[] = [];

  statuses.forEach((status) => {
    if (status === "draft") {
      statusWhereInput.push({
        deployedAt: null,
      });
    } else {
      statusWhereInput.push({
        status,
      });
    }
  });

  if (statusWhereInput.length > 0) {
    whereInputs.push({
      OR: statusWhereInput,
    });
  }

  const orderBy: Prisma.JobOrderByWithRelationInput[] =
    opts.sorting?.map((item) => {
      const field = item.id === "title" ? "title" : item.id;
      return {
        [field]: item.desc ? "desc" : "asc",
      };
    }) ?? [];

  if (searchQuery) {
    orderBy.unshift({
      _relevance: {
        fields: [
          "title",
          "description",
          "jobResponsibilities",
          "candidateDescription",
          "agentInstructions",
        ],
        search: searchQuery,
        sort: "desc",
      },
    });
  }

  if (looseSearchQuery) {
    orderBy.unshift({
      _relevance: {
        fields: ["title"],
        search: looseSearchQuery,
        sort: "desc",
      },
    });
  }

  const totalCount = opts.skipCount
    ? 0
    : await db.job.count({
        where: {
          organizationId: {
            in: organizationIds,
          },
          AND: whereInputs,
        },
      });

  if (pageIndex > 0 && pageIndex * pageSize >= totalCount) {
    throw new Error("Page index out of bounds");
  }

  const jobs = await db.job.findMany({
    where: {
      organizationId: {
        in: organizationIds,
      },
      AND: whereInputs,
    },
    skip: pageIndex * pageSize,
    take: pageSize,
    select: {
      id: true,
      title: true,
      status: true,
      deployedAt: true,
      lastActivatedAt: true,
      createdAt: true,
      atsId: true,
      clientId: true,
      source: true,
      organizationId: true,
      opportunities: {
        select: {
          status: true,
          action: true,
          engagements: {
            select: {
              id: true,
              durationSeconds: true,
            },
            where: {
              subStatus: {
                in: [
                  CallSubStatus.candidate_declined,
                  CallSubStatus.completed,
                  CallSubStatus.partial,
                  CallSubStatus.rejected,
                ],
              },
            },
          },
        },
      },
      variables: {
        select: {
          value: true,
          templateVariable: true,
        },
      },
      maxAccessibleCreationStep: true,
    },
    orderBy: [
      ...orderBy,
      {
        lastActivatedAt: {
          sort: "desc",
          nulls: "last",
        },
      },
      {
        createdAt: "desc",
      },
    ],
  });

  return {
    jobs: jobs.map((job) => ({
      id: job.id,
      title: job.title,
      createdAt: job.createdAt,
      deployedAt: job.deployedAt,
      status: job.status,
      lastActivatedAt: job.lastActivatedAt,
      atsId: job.atsId,
      clientId: job.clientId,
      organizationId: job.organizationId,
      companyName: getJobVariableValue(
        job.variables as JobVariableWithTemplateVariable[],
        variableKeys.CLIENT_NAME,
      ),
      jobLocation: getJobVariableValue(
        job.variables as JobVariableWithTemplateVariable[],
        variableKeys.JOB_LOCATION,
      ),
      source: job.source,
      maxAccessibleCreationStep: job.maxAccessibleCreationStep,
      ...getCandidateStats(job.opportunities),
      totalConversations: job.opportunities.reduce((acc, opportunity) => {
        return (
          acc +
          opportunity.engagements.filter(
            (engagement) =>
              engagement.durationSeconds > CONVERSATION_DURATION_SECONDS,
          ).length
        );
      }, 0),
    })) as JobTableRow[],
    totalCount,
  };
};

