      lastActivatedAt: true,
      timezone: true,
      publicAccessEnabledAt: true,
      variables: {
        include: {
          templateVariable: true,
        },
      },
      source: true,
      agentInstructions: true,
      knowledgeBase: true,
      headline: true,
      description: true,
      transcriptSummaryInstructions: true,
      scheduleRule: true,
      selectedAgentVoiceIds: true,
      maxAccessibleCreationStep: true,
      interviewPlan: true,
      callLanguage: true,
      allowedLanguages: true,
    },
  });

  // Generate ATS URL if job has an ATS integration
  const { getAtsUrl } = await import("./ats-instance-url");
  const atsUrl =
    job.atsId && job.source !== JobSource.MANUAL.toString()
      ? await getAtsUrl(organizationId, job.source, job.atsId, "job")
      : null;

  return {
    ...job,
    companyName: getJobVariableValue(
      job.variables as JobVariableWithTemplateVariable[],
      variableKeys.CLIENT_NAME,
    ),
    jobLocation: getJobVariableValue(
      job.variables as JobVariableWithTemplateVariable[],
      variableKeys.JOB_LOCATION,
    ),
    scheduleRule: scheduleRuleSchema.safeParse(job.scheduleRule).data ?? null,
    atsUrl,
  };
};

