export const updateJobIntegration = async ({
  organizationId,
  jobId,
  atsId,
  clientId,
  source,
}: {
  organizationId: string;
  jobId: string;
  atsId: string;
  clientId: string;
  source: JobSource;
}) => {
  // Check for duplicate ATS ID if it's not null or empty
  if (atsId && atsId.trim() !== "") {
    const existingJob = await db.job.findFirst({
      where: {
        organizationId,
        atsId: sanitizeAtsId(atsId),
        source,
        NOT: {
          id: jobId, // Exclude the current job from the check
        },
      },
      select: {
        id: true,
        title: true,
      },
    });

    if (existingJob) {
      throw new Error(
        `A job already exists in this organization with ATS ID "${atsId}" and the same job source. Please use a different ATS ID or update the existing job: "${existingJob.title}"`,
      );
    }
  }

  // Update the job with the new integration values
  await db.job.update({
    where: {
      id: jobId,
      organizationId,
    },
    data: {
      atsId: sanitizeAtsId(atsId),
      clientId: clientId.trim(),
      source,
    },
  });

  return getJobWithTemplate(organizationId, jobId);
};

