              .enum([
                JobQualificationType.MANDATORY,
                JobQualificationType.PREFERRED,
              ])
              .describe(
                "The type of the qualification. This should already be a part of the qualification object.",
              ),
          })
          .describe("A node in the call flow"),
      ),
      index: z
        .number()
        .describe(
          "The index of the node in the existing nodes array describing the pay rate",
        ),
    }),
    prompt: `
    I have a list of qualifications for a job that need to be inserted into a call flow of existing nodes.
    I need to know where in the call flow to insert the qualifications, and generate a new node for each qualification.

    When generating the list of nodes from the qualifications, use the following instructions:
    There will be a title for the node that is a short phrase that describes the qualification.
    Each node should have a prompt that instructs the agent to evaluate the candidate based on the qualification.
    The evaluation criteria should be a short phrase that describes the criteria that needs to be met for the node.
    It's usually helpful to phrase it in context of the candidate.

    Here are some examples of qualifications and how to format them into a node:
    "Must have 5 years of experience in software development":
    {
      "title": "Years of experience",
      "prompt": "How many years of experience do you have in software development?",
      "evaluationCriteria": "Candidate must have 5 years of experience",
    }

    If there is a qualification that is related to educational level, use the following instructions:
    If the qualification is that it requires a bachelor's degree, return the following two nodes:
    {
      "title": "Educational level - Bachelor's degree",
      "prompt": "Find out if the candidate has any college degrees, including the field of study. Reconfirm with the candidate that they have a college degree if you are not sure. Gather the year and the school where the degree was earned.",
      "evaluationCriteria": "Candidate has at least a college bachelor's degree",
      "followPromptStrictly": false
    }
    {
      "title": "No college degree",
      "prompt": "Tell the candidate: "Ok, I understand. Just so you know, this opportunity requires a college degree. We'll continue with the call in case I misinterpreted your response."",
      "shouldEndCall": false,
      "followPromptStrictly": false,
      "depth": 1,
      "conditionToEnter": {
        "scriptNodeTitle": "Educational level - Bachelor's degree",
        "evaluationMatches": "Candidate does not have at least a college bachelor's degree"
      },
      "required": false,
    }

    If the qualification is that it requires a high school degree or equivalent, return the following:
    {
      "title": "Educational level - High school degree",
      "prompt": "Find out the highest educational qualification the candidate has. Reconfirm with the candidate what their highest education qualification is if you are not sure. Gather the year and the school where the degree or diploma was earned.",
      "evaluationCriteria": "Candidate has at least a high school diploma or the equivalent such as a GED",
      "followPromptStrictly": false
    }
    {
      "title": "No high school diploma or GED",
      "prompt": "Tell the candidate: "Ok, I understand. Just so you know, this opportunity requires a high school diploma or the equivalent such as a GED. We'll continue with the call in case I misinterpreted your response."",
      "shouldEndCall": false,
      "followPromptStrictly": false,
      "depth": 1,
      "conditionToEnter": {
        "scriptNodeTitle": "Educational level - High school degree",
        "evaluationMatches": "Candidate does not have at least a high school diploma or the equivalent such as a GED"
      },
      "required": false,
    }

    Finally when generating the prompt for these qualifications, ${getAcronymConversionPrompt()}. Only do this 
    for the prompt and not for the title or the evaluation criteria.

    Here are the existing nodes in the call flow:
    ${JSON.stringify(existingNodes, null, 2)}

    Here are the qualifications to create new nodes for:
    ${JSON.stringify(qualifications, null, 2)}

    Figure out the requirement type of each qualification based on the type of the qualification. It will be either "mandatory" or "preferred".

    Finally, return the list of nodes, and find the index of the node in the existing nodes array where the title is "Pay Rate Confirmation Email".
    As an absolute last resort, if there is no such node, find the index in the existing nodes array where the title is "Job Description".
    Remember when calculating the index, the first node is at index 0, the second node is at index 1, and so on.
    `,
  });

  return result.object;
};

// Until we have the call flow schema that supports child nodes,
// we need to make sure that we are not inserting AI generated nodes
// between a parent node and its child nodes.
const validateNodeIndexToInsertAt = (
  index: number,
  nodes: ScriptNode[],
): number => {
  // if index is out of bounds, return the last index
  if (index < 0 || index > nodes.length) {
    return nodes.length - 1;
  }

  // If the index is the last node, we can insert at the end
  if (index === nodes.length - 1) {
    return index;
  }

  let followingNode = nodes[index + 1];
  // If the following node is a parent, we can safely insert after the current index
  if (followingNode?.depth === 0) {
    return index + 1;
  }

  // Find the next parent node, and insert right at it's index
  while (index < nodes.length - 1) {
    const followingNodeIndex = index + 1;
    followingNode = nodes[followingNodeIndex];

    if (followingNode?.depth === 0) {
      return followingNodeIndex;
    }
    index++;
  }

  return index;
};

export const insertVariablesInFlow = async (
  organizationId: string,
  jobId: string,
) => {
  const job = await db.job.findUniqueOrThrow({
    where: {
      id: jobId,
      organizationId,
    },
    include: {
      scriptTemplate: true,
      variables: {
        include: {
          templateVariable: true,
        },
      },
    },
  });
  if (!job.scriptTemplate) {
    throw new Error("Flow template not found");
  }
  const template = parseScriptNodes(
    job.scriptTemplate.template as Prisma.JsonObject,
  );

  // Replace template variables with their values in the template
  const { nodes } = await populateVariablesInFlow({
    nodes: template.nodes,
    variables: job.variables,
    shouldConvertAcronyms: true,
  });

  return db.job.update({
    where: {
      id: jobId,
      organizationId,
    },
    data: {
      callScript: {
        nodes,
      },
      maxAccessibleCreationStep: jobCreationSteps.qualifications.index,
    },
    include: {
      scriptTemplate: true,
    },
  });
};

export const generateNodesFromQualifications = async (
  organizationId: string,
  jobId: string,
) => {
  const job = await db.job.findUniqueOrThrow({
    where: {
      id: jobId,
      organizationId,
    },
    include: {
      qualifications: true,
      variables: {
        select: {
          value: true,
          templateVariable: {
            select: {
              key: true,
            },
          },
        },
      },
    },
  });

  const callScript = job.callScript as {
    nodes: ScriptNode[];
  };

  const nodesArray = callScript.nodes.filter((node) => !node.autoGenerated);

  const nodesWithIndex = nodesArray.map((node, index) => ({
    ...node,
    index,
  }));

  const qualificationsToInclude = job.qualifications.filter(
    (q) => q.shouldIncludeInFlow,
  );

  const { nodes: nodesFromQualifications, index } =
    await generateScriptNodesFromQualifications({
      qualifications: qualificationsToInclude,
      existingNodes: nodesWithIndex,
    });

  if (job.organizationId === MANAGED_STAFFING_ORG_ID) {
    const clientName = getJobVariableValue(
      job.variables as JobVariableWithTemplateVariable[],
      variableKeys.CLIENT_NAME,
    );

    const numSSNDigits =
      clientSpecificRequirements[clientName.toLowerCase()]?.numSSNDigits ?? 0;

    if (numSSNDigits > 0) {
      nodesFromQualifications.push(
        getSSNNode({
          clientName,
          numSSNDigits,
        }),
      );
    }
  }

  const nodesWithIds = nodesFromQualifications.map((node) => ({
    ...node,
    id: v4(),
  }));

  // assign parents to children nodes
  const formattedScriptNodes = nodesWithIds.map((rawNode) => {
    const node: ScriptNode = {
      ...rawNode,
      conditionToEnter: null,
    };

    const conditionToEnter = rawNode.conditionToEnter;
    if (conditionToEnter) {
      const existingNode = nodesWithIds.find(
        (parentNode) => parentNode.title === conditionToEnter.scriptNodeTitle,
      );
      if (existingNode) {
        node.conditionToEnter = {
          ...conditionToEnter,
          scriptNodeId: existingNode.id,
        };
      }
    }

    if (node.followPromptStrictly) {
      node.prompt = `${getRandomInterjection()}, and ${lowerFirst(node.prompt)}`;
    }

    return node;
  });

  const validatedIndex = validateNodeIndexToInsertAt(index, nodesArray);

  nodesArray.splice(validatedIndex, 0, ...formattedScriptNodes);

  const additionalDatapoints = {};

  return db.job.update({
    where: {
      id: jobId,
      organizationId,
    },
    data: {
      callScript: {
        nodes: nodesArray,
      },
      additionalDatapoints,
      maxAccessibleCreationStep: jobCreationSteps.flow.index,
    },
    include: {
      scriptTemplate: true,
    },
  });
};

