export const resyncJobVariables = async (
  organizationId: string,
  jobId: string,
): Promise<JobWithTemplate> => {
  const job = await db.job.findUniqueOrThrow({
    where: {
      id: jobId,
      organizationId,
    },
  });

  if (!job.scriptTemplateId) {
    throw new Error("Job has no script template");
  }

  const variablesToCreateForJob = await getVariablesToCreateForJob(
    job.scriptTemplateId,
    organizationId,
  );

  const jobDescriptionData = await getDataFromJobDescription({
    headline: job.headline,
    description: job.originalDescription ?? "",
    templateVariables: variablesToCreateForJob,
  });

  // recreate job variables based on new script template and job description
  await createJobVariables({
    jobId,
    templateVariables: variablesToCreateForJob,
    templateVariableValues: jobDescriptionData.object.templateVariables,
  });

  return getJobWithTemplate(organizationId, jobId);
};

