export async function saveJobQualifications({
  organizationId,
  jobId,
  qualifications,
}: {
  organizationId: string;
  jobId: string;
  qualifications: JobQualification[];
}): Promise<JobWithTemplate> {
  const mandatoryQualificationsForEmail = qualifications
    .filter(
      (q) =>
        q.type === (JobQualificationType.MANDATORY as string) &&
        (q.shouldIncludeInFlow || q.shouldIncludeInEmail),
    )
    .map((q) => q.value);
  const preferredQualificationsForEmail = qualifications
    .filter(
      (q) =>
        q.type === (JobQualificationType.PREFERRED as string) &&
        (q.shouldIncludeInFlow || q.shouldIncludeInEmail),
    )
    .map((q) => q.value);

  const mandatoryQualificationsString = formatAsBulletPoints(
    mandatoryQualificationsForEmail,
  );
  const preferredQualificationsString = formatAsBulletPoints(
    preferredQualificationsForEmail,
  );

  // TODO remove this once we only use the new notifications
  await db.job.update({
    where: {
      id: jobId,
      organizationId,
    },
    data: {
      requiredSkills: mandatoryQualificationsString,
      preferredSkills: preferredQualificationsString,
    },
  });

  await updateJobVariableValue({
    jobId,
    key: variableKeys.REQUIRED_QUALIFICATIONS,
    value: JSON.stringify(mandatoryQualificationsForEmail),
  });
  await updateJobVariableValue({
    jobId,
    key: variableKeys.PREFERRED_QUALIFICATIONS,
    value: JSON.stringify(preferredQualificationsForEmail),
  });

  await Promise.all(
    qualifications.map((qualification) => {
      return db.jobQualification.upsert({
        where: {
          id: qualification.id,
        },
        update: qualification,
        create: {
          ...qualification,
          jobId,
        },
      });
    }),
  );

  return getJobWithTemplate(organizationId, jobId);
}

export const insertJobVariablesInNotifications = async (
  organizationId: string,
  jobId: string,
) => {
  const job = await db.job.findUniqueOrThrow({
    where: {
      id: jobId,
      organizationId,
    },
    include: {
      notificationTemplates: true,
      variables: {
        include: {
          templateVariable: true,
        },
      },
    },
  });
  if (!job.notificationTemplates.length) {
    return job;
  }

  // Replace job variables with their values in the notifications
  const notifications = populateVariablesInNotifications({
    notifications: job.notificationTemplates,
    variables: job.variables
      .filter(
        (v) => v.templateVariable.type === TemplateVariableType.JOB.toString(),
      )
      .map((v) => ({
        key: v.templateVariable.key,
        value: v.value,
      })),
    replaceFromTemplate: true,
  });

  await Promise.all(
    notifications.map((notification) =>
      db.jobNotificationTemplate.update({
        where: {
          id: notification.id,
        },
        data: {
          subject: notification.subject,
          body: notification.body,
        },
      }),
    ),
  );

  return job;
};

