"use server";

import type {
  Engagement,
  JobNotificationTemplate,
  Organization,
  TemplateVariable,
} from "@purplefish-ai/db";
import {
  NotificationChannel,
  NotificationTemplateGroup,
} from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";
import {
  PrismaJsonCommsSequence,
  PrismaJsonRetryConfig,
} from "@purplefish-ai/db/types";
import { updateManagedStaffingJobNotificationTemplates } from "@/common/customers/managed-staffing";
import {
  getEngagementVariables,
  getOpportunityVariables,
  getOrganizationVariables,
  populateVariablesInNotifications,
} from "@/common/libs/variables";
import { jobCreationSteps } from "@/common/models/jobs";
import { defaultOrgNotificationTemplates } from "@/common/models/notification-templates";
import { sendEmailNotification } from "@/server/services/notification-email-sender";
import { insertJobVariablesInNotifications } from "../jobs";
import {
  OpportunityWithCandidate,
  sendSMSImmediately as sendOpportunitySMSImmediately,
} from "../opportunities";
import { getSystemTemplateVariables } from "../script-templates";
import type {
  OrgNotificationTemplateWithVariables,
  OrgNotificationVariableWithTemplateVariable,
} from "./types";
import {
  calculateVariableDifferences,
  combineTemplateText,
  extractUniqueVariableKeys,
  shouldSendNotification,
} from "./utils";

export async function createOrgNotificationTemplate(
  organizationId: string,
  data: {
    name: string;
    channel: NotificationChannel;
    body?: string;
  },
) {
  // create all default variables with it
  const notificationTemplate = await db.orgNotificationTemplate.create({
    data: {
      name: data.name,
      channel: data.channel,
      triggeredByState: "",
      body: data.body ?? "",
      organizationId,
    },
  });

  return getOrgNotificationTemplate(organizationId, notificationTemplate.id);
}

export async function getOrgNotificationTemplate(
  organizationId: string,
  id: string,
): Promise<OrgNotificationTemplateWithVariables> {
  return db.orgNotificationTemplate.findUniqueOrThrow({
    where: {
      id,
      organizationId,
    },
    include: {
      variables: {
        include: {
          templateVariable: true,
        },
      },
    },
  });
}

export async function getOrgNotificationTemplates({
  organizationId,
  onlyReturnEnabled = false,
}: {
  organizationId: string;
  onlyReturnEnabled?: boolean;
}): Promise<OrgNotificationTemplateWithVariables[]> {
  return db.orgNotificationTemplate.findMany({
    where: {
      organizationId,
      ...(onlyReturnEnabled
        ? {
            enabled: true,
          }
        : {}),
    },
    orderBy: {
      name: "asc",
    },
    include: {
      variables: {
        include: {
          templateVariable: true,
        },
      },
    },
  });
}

export async function updateOrgNotificationTemplate({
  organizationId,
  id,
  data,
}: {
  organizationId: string;
  id: string;
  data: {
    name: string;
    channel: NotificationChannel;
    subject?: string;
    body?: string;
    enabled: boolean;
    triggeredByState: string;
    group?: NotificationTemplateGroup | null;
    replyToRecruiter?: boolean;
  };
}) {
  const notificationTemplate = await db.orgNotificationTemplate.update({
    where: {
      id,
      organizationId,
    },
    data,
  });

  await updateVariablesInNotificationTemplate(notificationTemplate.id);

  return notificationTemplate;
}

export async function updateJobNotificationTemplate({
  organizationId,
  id,
  data,
}: {
  organizationId: string;
  id: string;
  data: {
    subject?: string;
    body?: string;
    enabled?: boolean;
    replyToRecruiter?: boolean;
  };
}) {
  // First verify that the notification template belongs to a job in this organization
  const template = await db.jobNotificationTemplate.findUniqueOrThrow({
    where: {
      id,
    },
    include: {
      job: {
        select: {
          organizationId: true,
        },
      },
    },
  });

  if (template.job.organizationId !== organizationId) {
    throw new Error(
      "Notification template does not belong to this organization",
    );
  }

  const notificationTemplate = await db.jobNotificationTemplate.update({
    where: {
      id,
    },
    data,
  });

  return notificationTemplate;
}

export async function getVariablesForNotificationTemplate(
  notificationTemplateId: string,
): Promise<OrgNotificationVariableWithTemplateVariable[]> {
  const variables = await db.orgNotificationVariable.findMany({
    where: {
      orgNotificationTemplateId: notificationTemplateId,
    },
    include: {
      templateVariable: true,
    },
  });

  return variables;
}

export const updateVariablesInNotificationTemplate = async (
  notificationTemplateId: string,
) => {
  const notificationTemplate =
    await db.orgNotificationTemplate.findUniqueOrThrow({
      where: {
        id: notificationTemplateId,
      },
    });

  const textToParse = combineTemplateText(
    notificationTemplate.subject,
    notificationTemplate.body,
  );

  const systemVariables = await getSystemTemplateVariables();
  const systemVariablesMap = systemVariables.reduce(
    (acc, variable) => {
      acc[variable.key] = variable;
      return acc;
    },
    {} as Record<string, TemplateVariable>,
  );

  const uniqueKeys = extractUniqueVariableKeys(textToParse, systemVariablesMap);

  const existingVariables = await getVariablesForNotificationTemplate(
    notificationTemplateId,
  );

  const { toDelete, toAdd } = calculateVariableDifferences(
    uniqueKeys,
    existingVariables,
  );

  // Delete variables that aren't in the template
  await Promise.all(
    toDelete.map((v) =>
      db.orgNotificationVariable.delete({
        where: {
          id: v.id,
        },
      }),
    ),
  );

  // Add new variables
  await Promise.all(
    toAdd.map(async (key) => {
      const systemVariable = systemVariablesMap[key];
      if (!systemVariable) {
        return;
      }
      return db.orgNotificationVariable.create({
        data: {
          orgNotificationTemplateId: notificationTemplateId,
          templateVariableId: systemVariable.id,
        },
      });
    }),
  );
};

export async function deleteOrgNotificationTemplate(
  organizationId: string,
  id: string,
) {
  await db.$transaction([
    db.orgNotificationVariable.deleteMany({
      where: {
        orgNotificationTemplateId: id,
      },
    }),
    db.orgNotificationTemplate.delete({
      where: {
        id,
        organizationId,
      },
    }),
  ]);
  return true;
}

export async function createDefaultOrgNotificationTemplates(
  organizationId: string,
) {
  const templates = await db.orgNotificationTemplate.createManyAndReturn({
    data: defaultOrgNotificationTemplates.map((template) => ({
      ...template,
      organizationId,
    })),
  });

  await Promise.all(
    templates.map((template) =>
      updateVariablesInNotificationTemplate(template.id),
    ),
  );
}

export const createJobNotificationTemplateFromOrgNotificationTemplate = async (
  jobId: string,
  orgNotificationTemplate: {
    enabled: boolean;
    name: string;
    channel: NotificationChannel;
    triggeredByState: string;
    body: string;
    subject: string | null;
    id: string;
    group: NotificationTemplateGroup | null;
    replyToRecruiter: boolean;
  },
) => {
  return db.jobNotificationTemplate.create({
    data: {
      jobId,
      name: orgNotificationTemplate.name,
      enabled: orgNotificationTemplate.enabled,
      channel: orgNotificationTemplate.channel,
      triggeredByState: orgNotificationTemplate.triggeredByState,
      bodyTemplate: orgNotificationTemplate.body,
      subjectTemplate: orgNotificationTemplate.subject,
      orgTemplateId: orgNotificationTemplate.id,
      group: orgNotificationTemplate.group,
      replyToRecruiter: orgNotificationTemplate.replyToRecruiter,
    },
  });
};

export async function createJobTemplateNotifications({
  organizationId,
  jobId,
}: {
  organizationId: string;
  jobId: string;
}) {
  // First, get the organization's commsSequence
  const organization = await db.organization.findUnique({
    where: {
      id: organizationId,
    },
    select: {
      commsSequence: true,
    },
  });

  const orgNotificationTemplates = await getOrgNotificationTemplates({
    organizationId,
  });

  const jobNotificationTemplates = await db.jobNotificationTemplate.findMany({
    where: {
      jobId,
    },
  });

  await Promise.all(
    jobNotificationTemplates.map(async (template) => {
      await db.opportunityNotification.deleteMany({
        where: {
          templateId: template.id,
        },
      });
    }),
  );

  await db.jobNotificationTemplate.deleteMany({
    where: {
      jobId,
    },
  });

  // Create job templates and keep track of the mapping
  const newJobTemplates = await Promise.all(
    orgNotificationTemplates.map((template) =>
      createJobNotificationTemplateFromOrgNotificationTemplate(jobId, template),
    ),
  );

  // Map org template IDs to job template IDs
  const templateIdMapping = new Map<string, string>();
  for (const jobTemplate of newJobTemplates) {
    if (jobTemplate.orgTemplateId) {
      templateIdMapping.set(jobTemplate.orgTemplateId, jobTemplate.id);
    }
  }

  // Map the organization's commsSequence template IDs and write to job in single operation
  if (organization?.commsSequence) {
    const mappedCommsSequence = await mapCommsSequenceTemplateIds(
      organization.commsSequence,
      templateIdMapping,
    );

    if (mappedCommsSequence) {
      await db.job.update({
        where: {
          id: jobId,
        },
        data: {
          commsSequence: mappedCommsSequence,
        },
      });
    }
  }

  // Special case for Managed Staffing
  await updateManagedStaffingJobNotificationTemplates({
    jobId,
    organizationId,
  });
  await insertJobVariablesInNotifications(organizationId, jobId);

  return db.job.update({
    where: {
      id: jobId,
    },
    data: {
      maxAccessibleCreationStep: jobCreationSteps.notifications.index,
    },
  });
}

/**
 * Maps org template IDs to job template IDs in a comms sequence
 */
export async function mapCommsSequenceTemplateIds(
  commsSequence: PrismaJsonCommsSequence | null | undefined,
  templateIdMapping: Map<string, string>,
): Promise<PrismaJsonCommsSequence | null | undefined> {
  if (!commsSequence) {
    return null;
  }

  // Check if it's a RetryConfig (new format)
  if ("retryIntervals" in commsSequence) {
    const updatedSequence = {
      ...commsSequence,
    } as PrismaJsonRetryConfig;

    // Map first action template ID if it exists
    if (updatedSequence.firstAction?.templateId) {
      const mappedId = templateIdMapping.get(
        updatedSequence.firstAction.templateId,
      );
      if (mappedId) {
        updatedSequence.firstAction.templateId = mappedId;
      }
    }

    // Map retry interval template IDs
    updatedSequence.retryIntervals = updatedSequence.retryIntervals.map(
      (interval) => {
        if (interval.action?.templateId) {
          const mappedId = templateIdMapping.get(interval.action.templateId);
          if (mappedId) {
            return {
              ...interval,
              action: {
                ...interval.action,
                templateId: mappedId,
              },
            };
          }
        }
        return interval;
      },
    );

    return updatedSequence;
  }

  // Return the original if it's a CommsConfig format
  return commsSequence;
}

export const getNotificationTemplatesForTrigger = async ({
  jobId,
  trigger,
}: {
  organizationId: string;
  jobId: string;
  trigger: string;
}) => {
  return db.jobNotificationTemplate.findMany({
    where: {
      jobId,
      triggeredByState: trigger,
      enabled: true,
    },
  });
};

export const sendOpportunityNotificationTemplate = async ({
  template,
  engagement,
  opportunity,
  organization,
  forceResend = false,
}: {
  template: JobNotificationTemplate;
  engagement?: Engagement | null;
  opportunity?: OpportunityWithCandidate | null;
  organization: Organization;
  forceResend?: boolean;
}) => {
  if (!opportunity) {
    console.log(
      `No opportunity found${engagement ? ` for engagement ${engagement.id}` : ""}, skipping notification template ${template.id}`,
    );
    return;
  }

  console.log(
    `Sending notification template ${template.id} for opportunity ${opportunity.id}${engagement ? ` (engagement ${engagement.id})` : ""} and organization ${organization.id} with forceResend: ${forceResend}`,
  );

  const previousOpportunityNotification =
    await db.opportunityNotification.findFirst({
      where: {
        opportunityId: opportunity.id,
        templateId: template.id,
      },
    });

  if (previousOpportunityNotification && !forceResend) {
    console.log(
      `Notification ${previousOpportunityNotification.id} for template ${template.id} for opportunity ${opportunity.id} has already been sent, skipping`,
    );
    return;
  }

  try {
    let opportunityNotification = null;
    if (!previousOpportunityNotification) {
      opportunityNotification = await db.opportunityNotification.create({
        data: {
          opportunityId: opportunity.id,
          templateId: template.id,
        },
      });
    } else {
      opportunityNotification = await db.opportunityNotification.update({
        where: {
          id: previousOpportunityNotification.id,
        },
        data: {
          updatedAt: new Date(),
        },
      });
    }

    if (template.channel === NotificationChannel.EMAIL) {
      await sendEmailNotification({
        subject: template.subject ?? "",
        body: template.body,
        to: opportunity.candidate.email,
        organizationId: organization.id,
        opportunityNotificationId: opportunityNotification.id,
        opportunityId: opportunity.id,
        candidateId: opportunity.candidateId,
        options: {
          replyTo: template.replyToRecruiter
            ? (opportunity.assignedToEmail ?? undefined)
            : undefined,
        },
      });
    } else {
      await sendOpportunitySMSImmediately({
        opportunityId: opportunity.id,
        message: template.body,
        opportunityNotificationId: opportunityNotification.id,
      });
    }
  } catch (err: unknown) {
    const errorMessage = err instanceof Error ? err.message : String(err);
    console.error(
      `Error sending email for template ${template.id} to opportunity ${opportunity.id}: ${errorMessage}`,
    );
  }
};

export const sendNotificationsForTrigger = async ({
  opportunityId,
  engagementId,
  trigger,
  forceResend = false,
}: {
  opportunityId: string;
  engagementId?: string;
  trigger: string;
  forceResend?: boolean;
}) => {
  const opportunity = await db.opportunity.findUniqueOrThrow({
    where: {
      id: opportunityId,
    },
    include: {
      candidate: true,
      job: {
        include: {
          variables: {
            include: {
              templateVariable: true,
            },
          },
          organization: true,
        },
      },
      tags: {
        include: {
          tag: true,
        },
      },
      agentPhoneNumber: true,
    },
  });

  let engagement: Engagement | null = null;
  if (engagementId) {
    engagement = await db.engagement.findUnique({
      where: {
        id: engagementId,
      },
    });
  }

  const { organization, jobId, messagingEnabled, salaryRequirementCents } = {
    organization: opportunity.job.organization,
    jobId: opportunity.job.id,
    messagingEnabled: opportunity.job.messagingEnabled,
    salaryRequirementCents: opportunity.salaryRequirementCents,
  };

  const templates = await getNotificationTemplatesForTrigger({
    organizationId: organization.id,
    jobId,
    trigger,
  });

  if (templates.length === 0) {
    console.log(
      `No notification templates found for trigger ${trigger} for job ${jobId}`,
    );
    return;
  }

  const organizationVariablesPromise = getOrganizationVariables({
    organization,
  });
  const opportunityVariablesPromise = getOpportunityVariables({
    opportunity,
  });

  let engagementVariables: {
    key: string;
    value: string;
  }[] = [];
  if (engagementId) {
    engagementVariables = await getEngagementVariables({
      engagementId,
      organizationId: organization.id,
      jobId,
      salaryRequirementCents: Number(salaryRequirementCents) || 0,
    });
  }

  const [organizationVariables, opportunityVariables] = await Promise.all([
    organizationVariablesPromise,
    opportunityVariablesPromise,
  ]);

  const populatedTemplates = populateVariablesInNotifications({
    notifications: templates,
    variables: [
      ...engagementVariables,
      ...organizationVariables,
      ...opportunityVariables,
    ],
    replaceFromTemplate: false,
  });

  await Promise.all(
    populatedTemplates.map(async (template) => {
      // Check if we should send this notification
      const { shouldSend, reason } = await shouldSendNotification(
        template,
        opportunity,
        messagingEnabled,
        forceResend,
      );

      if (!shouldSend) {
        console.log(
          `Opportunity ${opportunity.id}: ${reason}, not sending ${template.channel} notification for trigger ${trigger}.`,
        );
        return;
      }

      return sendOpportunityNotificationTemplate({
        template,
        engagement,
        opportunity,
        organization,
        forceResend,
      });
    }),
  );
};

