import { SequenceItemChannel } from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";

import { DEFAULT_SCHEDULE_RULE } from "@/common/constants/default-schedule-rule";
import { addRandomMinutesToDate } from "@/common/libs/add-random-minutes-to-date";
import { normalizeSequenceIntervals } from "@/common/libs/normalize-sequence-intervals";
import {
  getNextAvailableTime,
  scheduleRuleSchema,
} from "@/common/libs/schedule";
import { JobStatus } from "@/common/models/jobs";
import { inngest } from "@/server/inngest/client";

import { createAuditLog } from "./audit-trail";

const SEQUENCE_JITTER_MINUTES = 10;

export const triggerSequenceItemInngestRun = async (sequenceItem: {
  id: string;
  updatedAt: Date;
}) => {
  // Cancel the existing pending Inngest run
  await inngest.send({
    name: "purplefish/opportunity_sequence_item.cancelled",
    data: {
      sequenceItemId: sequenceItem.id,
    },
  });

  // Start new run with new scheduledAt
  const result = await inngest.send({
    name: "purplefish/opportunity_sequence_item.triggered",
    id: `${sequenceItem.id}-${sequenceItem.updatedAt.getTime()}`,
    data: {
      sequenceItemId: sequenceItem.id,
    },
  });

  await db.opportunitySequenceItem.update({
    where: {
      id: sequenceItem.id,
    },
    data: {
      inngestRunIds: {
        push: result.ids,
      },
    },
  });
};

export const cancelSequenceItem = async (
  sequenceItemId: string,
  cancelledReason: string,
) => {
  console.log(`Cancelling sequence item ${sequenceItemId}`);

  await inngest.send({
    name: "purplefish/opportunity_sequence_item.cancelled",
    data: {
      sequenceItemId,
    },
  });

  const updated = await db.opportunitySequenceItem.update({
    where: {
      id: sequenceItemId,
    },
    data: {
      cancelledAt: new Date(),
      cancelledReason,
    },
  });

  await createAuditLog({
    userId: null,
    action: "UPDATE",
    modelName: "Opportunity",
    recordId: updated.opportunityId,
    reason: cancelledReason,
    changes: {
      title: "Sequence item cancelled",
      channel: updated.channel,
      sequenceItemId,
      cancelledReason,
    },
  });
};

export const createSequenceItem = async ({
  opportunityId,
  channel,
  scheduledAt,
  templateId,
  triggeredByUserId,
}: {
  opportunityId: string;
  channel?: SequenceItemChannel;
  scheduledAt: Date;
  templateId?: string;
  triggeredByUserId?: string | null;
}) => {
  console.log(
    `Creating sequence item for opportunity ${opportunityId} with channel ${channel} and scheduledAt ${scheduledAt.toISOString()} and templateId ${templateId}`,
  );

  const sequenceItem = await db.opportunitySequenceItem.create({
    data: {
      opportunityId,
      channel,
      templateId,
      scheduledAt,
      triggeredByUserId,
    },
  });

  await inngest.send({
    name: "purplefish/opportunity_sequence_item.updated",
    data: {
      sequenceItemId: sequenceItem.id,
    },
  });

  await createAuditLog({
    userId: triggeredByUserId ?? null,
    action: "CREATE",
    modelName: "Opportunity",
    recordId: opportunityId,
    reason: "Sequence item created",
    changes: {
      title: "Sequence item created",
      sequenceItemId: sequenceItem.id,
      channel: channel ?? null,
      scheduledAt: scheduledAt.toISOString(),
      templateId: templateId ?? null,
    },
  });

  return sequenceItem;
};

export const rescheduleSequenceItem = async (
  sequenceItemId: string,
  scheduledAt: Date,
) => {
  const prev = await db.opportunitySequenceItem.findUnique({
    where: {
      id: sequenceItemId,
    },
    select: {
      id: true,
      opportunityId: true,
      scheduledAt: true,
    },
  });

  const sequenceItem = await db.opportunitySequenceItem.update({
    where: {
      id: sequenceItemId,
    },
    data: {
      scheduledAt,
    },
  });

  await inngest.send({
    name: "purplefish/opportunity_sequence_item.updated",
    data: {
      sequenceItemId: sequenceItem.id,
    },
  });

  if (prev) {
    await createAuditLog({
      userId: null,
      action: "UPDATE",
      modelName: "Opportunity",
      recordId: prev.opportunityId,
      reason: "Sequence item rescheduled",
      changes: {
        title: "Sequence item rescheduled",
        sequenceItemId: sequenceItem.id,
        from: prev.scheduledAt ? prev.scheduledAt.toISOString() : null,
        to: scheduledAt.toISOString(),
      },
    });
  }

  return sequenceItem;
};

export const cancelSequenceItems = async (
  opportunityId: string,
  cancelledReason: string,
) => {
  // Expire any existing untriggered/uncancelled sequence items
  const unexpiredSequenceItems = await db.opportunitySequenceItem.findMany({
    where: {
      opportunityId,
      triggeredAt: null,
      OR: [
        {
          cancelledAt: null,
        },
        {
          cancelledAt: {
            gt: new Date(),
          },
        },
      ],
    },
  });

  await db.opportunity.update({
    where: {
      id: opportunityId,
    },
    data: {
      sequenceInitializedAt: null,
    },
  });

  await Promise.all(
    unexpiredSequenceItems.map((item) =>
      cancelSequenceItem(item.id, cancelledReason),
    ),
  );

  await createAuditLog({
    userId: null,
    action: "UPDATE",
    modelName: "Opportunity",
    recordId: opportunityId,
    reason: cancelledReason,
    changes: {
      title: "Sequence cleared",
      cancelledCount: unexpiredSequenceItems.length,
    },
  });
};

export const populateSequenceItems = async (
  opportunityId: string,
): Promise<
  {
    channel: SequenceItemChannel;
    scheduledAt: Date;
    templateId?: string;
  }[]
> => {
  const opportunity = await db.opportunity.findUniqueOrThrow({
    where: {
      id: opportunityId,
    },
    include: {
      candidate: {
        select: {
          phoneNumber: true,
        },
      },
      job: {
        select: {
          id: true,
          status: true,
          timezone: true,
          variables: {
            include: {
              templateVariable: true,
            },
          },
          commsSequence: true,
          scheduleRule: true,
        },
      },
    },
  });

  // If the job is not active, do nothing
  if (opportunity.job.status !== JobStatus.ACTIVE.toString()) {
    console.warn(
      `Job ${opportunity.job.id} is not active, not populating sequence items for ${opportunity.id}`,
    );
    return [];
  }

  // If the job has no comms sequence, do nothing
  if (!opportunity.job.commsSequence) {
    console.warn(
      `Job ${opportunity.job.id} has no comms sequence, not scheduling next step for ${opportunity.id}`,
    );
    return [];
  }

  if (opportunity.sequenceInitializedAt) {
    console.warn(
      `Sequence already initialized for opportunity ${opportunityId}, skipping`,
    );
    return [];
  }

  const sequenceMsIntervals = normalizeSequenceIntervals(
    opportunity.job.commsSequence,
  );

  if (sequenceMsIntervals.length === 0) {
    console.warn(
      `Job ${opportunity.job.id} has no normalized sequence intervals, not scheduling next step for ${opportunity.id}`,
    );
    return [];
  }

  // Expire any existing untriggered/uncancelled sequence items
  await cancelSequenceItems(opportunityId, "Sequence restarted");

  console.log(
    `Populating sequence items for opportunity ${opportunityId} with ${sequenceMsIntervals.length} intervals`,
  );

  const sequenceItems: {
    channel: SequenceItemChannel;
    scheduledAt: Date;
    templateId?: string;
  }[] = [];

  let scheduledAt = new Date();
  for (const interval of sequenceMsIntervals) {
    scheduledAt = new Date(scheduledAt.getTime() + interval.milliseconds);

    // Only apply calling hours for phone and SMS channels
    // Emails can be sent at any time
    if (interval.channel !== SequenceItemChannel.email) {
      scheduledAt = getNextAvailableTime(
        opportunity.job.timezone,
        scheduleRuleSchema.safeParse(opportunity.job.scheduleRule).data ??
          DEFAULT_SCHEDULE_RULE,
        scheduledAt,
      );
    }

    // Add jitter to sequence items during initial population to avoid clustering
    const scheduledAtWithJitter = addRandomMinutesToDate(
      scheduledAt,
      SEQUENCE_JITTER_MINUTES,
    );

    console.log(
      `Adding jitter to sequence item for opportunity ${opportunityId}. Original time: ${scheduledAt.toISOString()}, New time with jitter: ${scheduledAtWithJitter.toISOString()}`,
    );

    sequenceItems.push({
      channel: interval.channel,
      scheduledAt: scheduledAtWithJitter,
      templateId: interval.templateId,
    });
  }

  await Promise.all(
    sequenceItems.map((item) =>
      createSequenceItem({
        opportunityId,
        channel: item.channel,
        scheduledAt: item.scheduledAt,
        templateId: item.templateId,
      }),
    ),
  );

  await db.opportunity.update({
    where: {
      id: opportunityId,
    },
    data: {
      sequenceInitializedAt: new Date(),
    },
  });

  await createAuditLog({
    userId: null,
    action: "UPDATE",
    modelName: "Opportunity",
    recordId: opportunityId,
    reason: "Sequence initialized",
    changes: {
      title: "Sequence initialized",
      count: sequenceItems.length,
    },
  });

  return sequenceItems;
};

export const getNextPendingSequenceItem = async (
  opportunityId: string,
  channel: SequenceItemChannel,
) => {
  const sequenceItem = await db.opportunitySequenceItem.findFirst({
    where: {
      opportunityId,
      triggeredAt: null,
      cancelledAt: null,
      channel,
    },
    orderBy: {
      scheduledAt: "asc",
    },
  });

  if (!sequenceItem) {
    return null;
  }

  return sequenceItem;
};

