"use server";

import { OpportunityStatus } from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";

import { MANAGED_STAFFING_ORG_ID } from "@/common/libs/constants";
import { JobStatus } from "@/common/models/jobs";
import {
  defaultInterviewPlan,
  IInterviewPlan,
  stages,
} from "@/common/models/stages";

import { inngest } from "../inngest/client";
import { createAuditLog } from "./audit-trail";
import { updateOpportunity } from "./opportunities";

export const createDefaultInterviewPlan = async ({
  jobId,
}: {
  jobId: string;
}) => {
  await db.job.update({
    where: {
      id: jobId,
    },
    data: {
      interviewPlan: defaultInterviewPlan,
    },
  });
};

export const getOpportunityInitialStageId = async ({
  jobId,
}: {
  jobId: string;
}) => {
  const job = await db.job.findUnique({
    where: {
      id: jobId,
    },
    select: {
      status: true,
    },
  });

  if (!job) {
    return null;
  }

  const interviewPlan = await getInterviewPlan({
    jobId,
  });

  if (!interviewPlan) {
    return null;
  }

  return job.status === JobStatus.ACTIVE.toString()
    ? interviewPlan.initialActiveStageId
    : interviewPlan.initialInactiveStageId;
};

export const getInterviewPlan = async ({ jobId }: { jobId: string }) => {
  const job = await db.job.findUnique({
    where: {
      id: jobId,
    },
    select: {
      interviewPlan: true,
    },
  });

  return job?.interviewPlan as IInterviewPlan | null;
};

export const changeStage = async ({
  organizationId,
  opportunityId,
  currentStageId,
  nextStageId,
  userId,
  reason,
  skipEvents,
}: {
  organizationId: string;
  opportunityId: string;
  currentStageId: string | null;
  nextStageId: string;
  userId: string | null;
  reason: string;
  skipEvents?: boolean;
}) => {
  if (currentStageId === nextStageId) {
    return;
  }

  const result = await updateOpportunity({
    organizationId,
    opportunityId,
    data: {
      currentStageId: nextStageId,
    },
  });

  console.log(
    `Stage changed: ${currentStageId} -> ${nextStageId} for opportunity ${opportunityId}, actioned by ${userId ? `user ${userId}` : "system"} with reason: ${reason}`,
  );

  // TODO Currently just used for migrations, let's remove this once we're migrated
  if (skipEvents) {
    await createAuditLog({
      userId,
      action: "UPDATE",
      modelName: "Opportunity",
      recordId: opportunityId,
      reason,
      changes: {
        stageId: nextStageId,
        title: "Stage entered",
      },
    });

    return result;
  }

  await inngest.send({
    name: "purplefish/stage.exited",
    data: {
      organizationId,
      opportunityId,
      stageId: currentStageId!,
      userId,
    },
  });

  await inngest.send({
    name: "purplefish/stage.entered",
    data: {
      organizationId,
      opportunityId,
      stageId: nextStageId,
      userId,
      reason,
    },
  });

  return result;
};

const shouldArchiveOpportunity = ({
  doNotCall,
  organizationId,
  source,
  phoneNumber,
  email,
}: {
  doNotCall: boolean;
  organizationId: string;
  source: string | null;
  phoneNumber: string | null;
  email: string | null;
}) => {
  if (doNotCall) {
    return {
      shouldArchive: true,
      archiveReason: "Candidate has do not call set",
    };
  }

  if (!phoneNumber && !email) {
    return {
      shouldArchive: true,
      archiveReason:
        "Auto-archived: candidate missing both email and phone number",
    };
  }

  if (organizationId === MANAGED_STAFFING_ORG_ID) {
    if (source?.toLowerCase() === "job fair") {
      return {
        shouldArchive: true,
        archiveReason: "Auto-archived since source is Job Fair",
      };
    }
  }

  return {
    shouldArchive: false,
    archiveReason: null,
  };
};

const determineInitialStage = async ({
  opportunityId,
}: {
  opportunityId: string;
}) => {
  const opportunity = await db.opportunity.findUnique({
    where: {
      id: opportunityId,
    },
    select: {
      job: {
        select: {
          id: true,
          commsSequence: true,
          organizationId: true,
          status: true,
        },
      },
      source: true,
      candidate: {
        select: {
          doNotCall: true,
          phoneNumber: true,
          email: true,
        },
      },
    },
  });

  if (!opportunity) {
    throw new Error(
      `Opportunity not found for id: ${opportunityId} in determineInitialStage`,
    );
  }

  const initialStageId = await getOpportunityInitialStageId({
    jobId: opportunity.job.id,
  });

  const isInitialStageInactive = initialStageId === stages.INACTIVE;
  const isInitialStagePhoneScreen = initialStageId === stages.PHONE_SCREEN;
  const isInitialStageOptIn = initialStageId === stages.OPT_IN;
  const isJobInactive = opportunity.job.status !== JobStatus.ACTIVE.toString();

  const { shouldArchive, archiveReason } = shouldArchiveOpportunity({
    doNotCall: opportunity.candidate.doNotCall,
    organizationId: opportunity.job.organizationId,
    source: opportunity.source,
    phoneNumber: opportunity.candidate.phoneNumber,
    email: opportunity.candidate.email,
  });

  let nextStageId: string | null = null;
  let reason: string | null = null;

  if (shouldArchive) {
    nextStageId = stages.ARCHIVED;
    reason = archiveReason;
  } else if (isJobInactive) {
    // If job is inactive, always use initialInactiveStageId regardless of phone number
    nextStageId = initialStageId;
    reason = "Job is inactive, using configured inactive stage";
  } else if (!opportunity.candidate.phoneNumber) {
    // Handle missing phone number scenario for active jobs only
    const interviewPlan = await getInterviewPlan({
      jobId: opportunity.job.id,
    });
    nextStageId =
      interviewPlan?.initialActiveStageIdWhenNoPhoneNumber ?? stages.ARCHIVED;
    reason =
      "Moving candidate to configured stage for candidates without phone numbers";
  } else if (isInitialStageInactive || isInitialStageOptIn) {
    nextStageId = initialStageId;
    reason = "Initial opportunity stage dictated by configuration";
  } else if (isInitialStagePhoneScreen) {
    if (opportunity.job.commsSequence) {
      nextStageId = stages.PHONE_SCREEN;
      reason = "Initial opportunity stage dictated by configuration";
    } else {
      nextStageId = stages.INACTIVE;
      reason =
        "Candidate set to inactive since job is not sequenced or sequencing is disabled";
    }
  }

  return {
    nextStageId,
    reason,
  };
};

const getNextStageFromOpportunityStatus = ({
  status,
}: {
  status: OpportunityStatus;
}): {
  nextStageId: string | null;
  reason: string;
} => {
  // Automatically move candidates for Opportunity Ending Events
  switch (status) {
    case OpportunityStatus.completed:
      return {
        nextStageId: stages.COMPLETED,
        reason: "Opportunity completed, moving to completed",
      };
    case OpportunityStatus.sequence_ended:
      return {
        nextStageId: stages.ARCHIVED,
        reason: "Opportunity sequence ended, moving to archived",
      };
    case OpportunityStatus.candidate_declined:
      return {
        nextStageId: stages.ARCHIVED,
        reason: "Opportunity declined by candidate, moving to archived",
      };
    default:
      return {
        nextStageId: null,
        reason: "No next stage found for status",
      };
  }
};

// This will be handled by Puppeteering agent in the future
export const moveOpportunityToNextStage = async ({
  opportunityId,
}: {
  opportunityId: string;
}) => {
  const opportunity = await db.opportunity.findUnique({
    where: {
      id: opportunityId,
    },
    select: {
      status: true,
      currentStageId: true,
      candidate: {
        select: {
          phoneNumber: true,
          doNotCall: true,
          id: true,
          email: true,
        },
      },
      job: {
        select: {
          id: true,
          organizationId: true,
        },
      },
    },
  });

  if (!opportunity) {
    throw new Error(
      `Opportunity not found for id: ${opportunityId} in moveOpportunityToNextStage`,
    );
  }

  const currentStageId = opportunity.currentStageId;

  // If the opportunity has no current stage, or the current stage is still inactive,
  // we need to determine the initial stage
  if (!opportunity.currentStageId || currentStageId === stages.INACTIVE) {
    const { nextStageId, reason } = await determineInitialStage({
      opportunityId,
    });

    if (!nextStageId || !reason) {
      throw new Error(
        `No next stage found for opportunity ${opportunityId} in moveOpportunityToNextStage`,
      );
    }

    await changeStage({
      organizationId: opportunity.job.organizationId,
      opportunityId,
      currentStageId: null,
      nextStageId,
      userId: null,
      reason,
    });

    return nextStageId;
  }

  const { nextStageId, reason } = getNextStageFromOpportunityStatus({
    status: opportunity.status,
  });

  if (nextStageId) {
    await changeStage({
      organizationId: opportunity.job.organizationId,
      opportunityId,
      currentStageId,
      nextStageId,
      userId: null,
      reason,
    });
  } else {
    console.log(
      `No next stage found for opportunity ${opportunityId} and current stage ${currentStageId}, with opportunity status ${opportunity.status}`,
    );
  }

  return nextStageId;
};

